content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: #0f172a;
  color: #f8fafc;
  overflow: hidden;
  width: 100vw;
  height: 100vh;
  user-select: none;
}

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at center, #1e1b4b 0%, #0f172a 100%);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
}

.canvas {
  display: block;
  width: 100%;
  height: 100%;
}

.info-overlay {
  position: absolute;
  top: 24px;
  left: 24px;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.subtitle {
  font-size: 0.875rem;
  color: #94a3b8;
}

.controls {
  position: absolute;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 10;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  background: rgba(15, 23, 42, 0.75);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  padding: 12px 20px;
  border-radius: 16px;
  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5);
  max-width: 90vw;
  justify-content: center;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.btn {
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #cbd5e1;
  padding: 8px 14px;
  font-size: 0.875rem;
  font-weight: 500;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.btn:hover {
  background: rgba(51, 65, 85, 0.9);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.2);
  transform: translateY(-1px);
}

.btn:active {
  transform: translateY(0);
}

.btn-active {
  background: linear-gradient(135deg, #3b82f6 0%, #6366f1 100%);
  color: #ffffff;
  border-color: rgba(255, 255, 255, 0.3);
  box-shadow: 0 0 15px rgba(59, 130, 246, 0.4);
}

@media (max-width: 768px) {
  .controls {
    bottom: 16px;
    padding: 10px 14px;
    gap: 10px;
  }

  .btn {
    padding: 6px 10px;
    font-size: 0.75rem;
  }

  .info-overlay {
    top: 16px;
    left: 16px;
  }

  .title {
    font-size: 1.2rem;
  }
}

import { useEffect, useRef, useState, useCallback } from 'react';
import './index.css';

type ParticleMode = 'swirl' | 'explode' | 'matrix';
type ColorTheme = 'neon' | 'sunset' | 'rainbow';

interface Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  color: string;
  alpha: number;
  life: number;
  maxLife: number;
}

export default function App() {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [particleMode, setParticleMode] = useState<ParticleMode>('swirl');
  const [colorTheme, setColorTheme] = useState<ColorTheme>('neon');

  const mouseRef = useRef({ x: window.innerWidth / 2, y: window.innerHeight / 2, active: false });
  const particlesRef = useRef<Particle[]>([]);

  const getColors = useCallback((theme: ColorTheme): string[] => {
    switch (theme) {
      case 'sunset':
        return ['#f43f5e', '#fb923c', '#facc15', '#ec4899'];
      case 'rainbow':
        return ['#38bdf8', '#818cf8', '#c084fc', '#f43f5e', '#34d399'];
      case 'neon':
      default:
        return ['#06b6d4', '#3b82f6', '#8b5cf6', '#ec4899', '#10b981'];
    }
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current = { x: e.clientX, y: e.clientY, active: true };
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length > 0) {
        mouseRef.current = { x: e.touches[0].clientX, y: e.touches[0].clientY, active: true };
      }
    };

    const handleMouseLeave = () => {
      mouseRef.current.active = false;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('touchmove', handleTouchMove);
    window.addEventListener('mouseleave', handleMouseLeave);

    const colors = getColors(colorTheme);

    const createParticles = (x: number, y: number) => {
      const count = particleMode === 'explode' ? 5 : 2;
      for (let i = 0; i < count; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = particleMode === 'explode' ? Math.random() * 8 + 2 : Math.random() * 3 + 1;
        particlesRef.current.push({
          x,
          y,
          vx: Math.cos(angle) * speed,
          vy: Math.sin(angle) * speed,
          size: Math.random() * 4 + 2,
          color: colors[Math.floor(Math.random() * colors.length)],
          alpha: 1,
          life: 0,
          maxLife: Math.random() * 40 + 30,
        });
      }
    };

    const render = () => {
      ctx.fillStyle = 'rgba(15, 23, 42, 0.2)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      if (mouseRef.current.active) {
        createParticles(mouseRef.current.x, mouseRef.current.y);
      } else {
        // 自動生成（アイドル時）
        createParticles(canvas.width / 2 + Math.sin(Date.now() * 0.002) * 100, canvas.height / 2 + Math.cos(Date.now() * 0.003) * 100);
      }

      const particles = particlesRef.current;
      for (let i = particles.length - 1; i >= 0; i--) {
        const p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.life++;
        p.alpha = 1 - p.life / p.maxLife;

        if (particleMode === 'swirl') {
          p.vx *= 0.96;
          p.vy *= 0.96;
        } else if (particleMode === 'matrix') {
          p.vy += 0.2;
        }

        if (p.life >= p.maxLife || p.alpha <= 0) {
          particles.splice(i, 1);
          continue;
        }

        ctx.save();
        ctx.globalAlpha = Math.max(0, p.alpha);
        ctx.fillStyle = p.color;
        ctx.shadowBlur = 10;
        ctx.shadowColor = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('mouseleave', handleMouseLeave);
      cancelAnimationFrame(animationFrameId);
    };
  }, [particleMode, colorTheme, getColors]);

  return (
    <div className="app-container">
      <div className="info-overlay">
        <h1 className="title">パーティクル・エフェクト</h1>
        <p className="subtitle">マウスやタッチで美しく輝く軌跡を描こう</p>
      </div>

      <div className="canvas-container">
        <canvas ref={canvasRef} className="canvas" />
      </div>

      <div className="controls">
        <div className="control-group">
          <button 
            className={`btn ${particleMode === 'swirl' ? 'btn-active' : ''}`}
            onClick={() => setParticleMode('swirl')}
          >
            渦巻き
          </button>
          <button 
            className={`btn ${particleMode === 'explode' ? 'btn-active' : ''}`}
            onClick={() => setParticleMode('explode')}
          >
            爆発
          </button>
          <button 
            className={`btn ${particleMode === 'matrix' ? 'btn-active' : ''}`}
            onClick={() => setParticleMode('matrix')}
          >
            重力
          </button>
        </div>

        <div className="control-group">
          <button 
            className={`btn ${colorTheme === 'neon' ? 'btn-active' : ''}`}
            onClick={() => setColorTheme('neon')}
          >
            ネオン
          </button>
          <button 
            className={`btn ${colorTheme === 'sunset' ? 'btn-active' : ''}`}
            onClick={() => setColorTheme('sunset')}
          >
            サンセット
          </button>
          <button 
            className={`btn ${colorTheme === 'rainbow' ? 'btn-active' : ''}`}
            onClick={() => setColorTheme('rainbow')}
          >
            レインボー
          </button>
        </div>
      </div>
    </div>
  );
}
